gr2(){return"Model management"},
gr4(){return"Auto update check"},
grh(){return"Transformer (40%)"},
grf(){return"Statistical analysis (25%)"},
grg(){return"Stylometry (20%)"},
grd(){return"Adversarial defense (15%)"},
