gu_(){return"\uc774 \uc571\uc758 \ud575\uc2ec AI \uac10\uc9c0\ub294 \uc644\uc804\ud788 \uae30\uae30 \ub0b4\uc5d0\uc11c \uc2e4\ud589\ub418\uc9c0\ub9cc, \ub2e4\uc74c \uc138 \uac00\uc9c0 \uae30\ub2a5\uc740 \ub124\ud2b8\uc6cc\ud06c \uc5f0\uacb0\uc774 \ud544\uc694\ud569\ub2c8\ub2e4:"},
gtW(){return"1. \ubaa8\ub378 \uce74\ud0c8\ub85c\uadf8 \ubc0f \ub2e4\uc6b4\ub85c\ub4dc: GitHub Releases\uff0fHugging Face\uc5d0 \uc5f0\uacb0\ud558\uc5ec \uc120\ud0dd\ud55c \uac10\uc9c0 \ubaa8\ub378 \ud30c\uc77c\uc744 \ub2e4\uc6b4\ub85c\ub4dc\ud569\ub2c8\ub2e4. \ubaa8\ub378 \ub2e4\uc6b4\ub85c\ub4dc\ub9cc \uc218\ud589\ud558\uba70 \uc0ac\uc6a9\uc790 \ub370\uc774\ud130\ub97c \uc5c5\ub85c\ub4dc\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
gtX(){return"2. \ubaa8\ub378 \uc5c5\ub370\uc774\ud2b8 \ud655\uc778: \uc2e4\ud589 \uc2dc \ubc84\uc804 \ubc88\ud638\ub9cc \ube44\uad50\ud558\uae30 \uc704\ud574 \uc5f0\uacb0\ud558\uba70, \uc0c8 \ubc84\uc804\uc774 \uc788\ub294\uc9c0 \uc54c\ub9ac\ub294 \ub370 \uc0ac\uc6a9\ub429\ub2c8\ub2e4."},
gtY(){return'3. \ud558\uc774\ud37c\ub9c1\ud06c \ubc0f \uc778\uc6a9 \ubb38\ud5cc \uc2e4\uc7ac\uc131 \uac80\uc99d: \uae30\ubcf8\uc801\uc73c\ub85c \ucf1c\uc838 \uc788\uc73c\uba70 "\uc124\uc815"\uc5d0\uc11c \ub04c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ucf1c\uc838 \uc788\uc73c\uba74 \ubb38\uc11c\uc5d0\uc11c \uac10\uc9c0\ub41c URL\uc774\ub098 \ucc38\uace0 \ubb38\ud5cc \ud14d\uc2a4\ud2b8\ub97c \ud574\ub2f9 URL \uc790\uccb4 \ub610\ub294 Crossref \uacf5\uac1c API\ub85c \uc9c1\uc811 \uc804\uc1a1\ud569\ub2c8\ub2e4. URL\uff0fDOI\uff0f\uc11c\uc9c0 \uc815\ubcf4 \ud14d\uc2a4\ud2b8\ub9cc \uc804\uc1a1\ud558\uba70 \ubb38\uc11c\uc758 \ub2e4\ub978 \ub0b4\uc6a9\uc740 \ud3ec\ud568\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.'},
