gv3(){return"\u042d\u043a\u0441\u043f\u043e\u0440\u0442 \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0438 \u0441\u0432\u043e\u0434\u043a\u0438 (PNG)"},
v4(a){return"\u042d\u043a\u0441\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043e: "+a},
v1(a){return"\u041e\u0448\u0438\u0431\u043a\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430: "+a},
gu2(){return"\u0417\u043d\u0430\u043a 100% \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u043e\u0439 \u043a\u043e\u043d\u0444\u0438\u0434\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u0438 TruthLens: \u041e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430 \u043d\u0430 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435 \u0431\u0435\u0437 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044f \u0432 \u043e\u0431\u043b\u0430\u043a\u0435."},
guN(){return"\u0421\u043e\u043e\u0431\u0449\u0435\u0441\u0442\u0432\u043e (HuggingFace)"},
guR(){return"\u0414\u0435\u0442\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0434\u0432\u0438\u0436\u043a\u043e\u0432"},
guQ(){return"\u0423\u0440\u043e\u0432\u043d\u0438 \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u0434\u0432\u0438\u0436\u043a\u043e\u0432"},
gvy(){return"\u041a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440 Transformer"},
gvw(){return"\u0421\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0430\u043d\u0430\u043b\u0438\u0437"},
gvx(){return"\u0421\u0442\u0438\u043b\u043e\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0430\u043d\u0430\u043b\u0438\u0437"},
gvv(){return"\u0421\u043e\u0441\u0442\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0437\u0430\u0449\u0438\u0442\u0430"},
gvu(){return"\u041a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0439"},
