gnj(){return"\u0418\u043c\u043f\u043e\u0440\u0442"},
gkv(){return"\u0420\u0430\u0437\u0431\u043e\u0440"},
gni(){return"\u0410\u043d\u0430\u043b\u0438\u0437 \u0447\u0435\u0442\u044b\u0440\u044c\u043c\u044f \u043c\u043e\u0434\u0443\u043b\u044f\u043c\u0438"},
gnl(){return"\u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430"},
